import React from "react";
import { Tile } from "../tile/Tile.js";

export const TileList = ({tiles}) => {
  return (
    <div>
      {tiles.map((tile, index) => {
        const { name, ...descrption } = tile;
        return ( 
        <Tile 
          key={index}
          name={name}
          descripton={descrption}
        />
        )
      })};
    </div>
  );
};
